    var captureStats=new LinkedHashMap<String,Object>();captureStats.put("captured",captured());for(String f:List.of("received","processingErrors","dropped","sizeExcluded","queueOverflow"))captureStats.put(f,field(wb,f).toString());Files.writeString(out.resolve("capture-statistics.json"),MetadataExport.json(captureStats));
