  void finish(Throwable error){try{if(error!=null){error.printStackTrace();checks.add(Map.of("id","HARNESS","feature","runtime","title","하네스 완료","status","ERROR","reason",error.getClass().getSimpleName()+": "+Objects.toString(error.getMessage(),"")));}Map<String,Object> result=new LinkedHashMap<>();result.put("extensionVersion",BuildInfo.VERSION);result.put("burpVersion",burpVersion);result.put("javaVersion",System.getProperty("java.version"));result.put("transport","actual Burp Community Montoya HTTP; unmodified released Workbench JAR");result.put("checks",checks);result.put("authComparisons",comparisons);result.put("httpRequests",sent.get());result.put("completed",error==null);Files.writeString(Path.of(System.getProperty("qa.out")).resolve("extension-results.json"),MetadataExport.json(result));api.extension().unload();}catch(Throwable e){e.printStackTrace();error=e;}System.out.println("OSS_LAB_FINISHED");System.exit(error==null?0:1);}
